package org.eclipse.rdf4j.sail.helpers;

import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.CALLS_REAL_METHODS;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.withSettings;

import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;

import org.eclipse.rdf4j.common.iteration.CancellationSignal;
import org.eclipse.rdf4j.common.iteration.CloseableIteration;
import org.eclipse.rdf4j.common.iteration.EmptyIteration;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.sail.SailException;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;

class AbstractSailConnectionPatternShutdownTest {

	@Test
	void patternReadComposesAndRestoresTheCallerCancellationSignal() {
		AbstractSail sail = mock(AbstractSail.class,
				withSettings().useConstructor().defaultAnswer(CALLS_REAL_METHODS));
		AbstractSailConnection connection = mock(AbstractSailConnection.class,
				withSettings().useConstructor(sail).defaultAnswer(CALLS_REAL_METHODS));
		StatementPattern pattern = new StatementPattern(new Var("s"), new Var("p"), new Var("o"));
		AtomicReference<CancellationSignal> admitted = new AtomicReference<>();
		doAnswer(invocation -> {
			admitted.set(CancellationSignal.current());
			return new EmptyIteration<Statement>();
		}).when(connection).getStatementsInternal(pattern, null, null, null, false);
		CancellationSignal caller = new CancellationSignal();
		CancellationSignal previous = CancellationSignal.swapCurrent(caller);
		try {
			try (CloseableIteration<? extends Statement> result = connection.getStatements(pattern, null, null, null,
					false)) {
				assertThat(result.hasNext()).isFalse();
			}
			assertThat(CancellationSignal.current()).isSameAs(caller);
			assertThat(admitted.get()).isNotNull().isNotSameAs(CancellationSignal.NONE);
			caller.cancel();
			assertThat(admitted.get().isCancelled()).isTrue();
		} finally {
			CancellationSignal.restoreCurrent(previous);
			connection.close();
		}
	}

	@Test
	@Timeout(45)
	void closeInterruptsAndDrainsBothPatternReadWorkers() throws Exception {
		AbstractSail sail = mock(AbstractSail.class,
				withSettings().useConstructor().defaultAnswer(CALLS_REAL_METHODS));
		AbstractSailConnection connection = mock(AbstractSailConnection.class,
				withSettings().useConstructor(sail).defaultAnswer(CALLS_REAL_METHODS));
		StatementPattern pattern = new StatementPattern(new Var("s"), new Var("p"), new Var("o"));
		CountDownLatch entered = new CountDownLatch(2);
		CountDownLatch interrupted = new CountDownLatch(2);
		CountDownLatch release = new CountDownLatch(1);
		AtomicBoolean teardownStarted = new AtomicBoolean();
		doAnswer(invocation -> {
			teardownStarted.set(true);
			return null;
		}).when(connection).closeInternal();
		doAnswer(invocation -> {
			entered.countDown();
			boolean cancelled = false;
			while (release.getCount() != 0) {
				try {
					release.await();
				} catch (InterruptedException e) {
					if (!cancelled) {
						cancelled = true;
						interrupted.countDown();
					}
				}
			}
			if (cancelled) {
				Thread.currentThread().interrupt();
				throw new SailException("pattern read interrupted during shutdown");
			}
			return new EmptyIteration<Statement>();
		}).when(connection).getStatementsInternal(pattern, null, null, null, false);

		AtomicReference<Throwable> firstFailure = new AtomicReference<>();
		AtomicReference<Throwable> secondFailure = new AtomicReference<>();
		AtomicReference<Throwable> closeFailure = new AtomicReference<>();
		Thread first = new Thread(() -> read(connection, pattern, firstFailure), "first-pattern-read");
		Thread second = new Thread(() -> read(connection, pattern, secondFailure), "second-pattern-read");
		Thread closer = new Thread(() -> {
			try {
				connection.close();
			} catch (Throwable failure) {
				closeFailure.set(failure);
			}
		}, "pattern-read-closer");

		try {
			first.start();
			second.start();
			assertTrue(entered.await(10, TimeUnit.SECONDS), "both pattern reads must enter their delegate");
			closer.start();
			assertTrue(interrupted.await(15, TimeUnit.SECONDS), "close must interrupt both active pattern reads");
			assertThat(teardownStarted.get()).as("native teardown must wait for both delegates").isFalse();
		} finally {
			release.countDown();
			first.join(TimeUnit.SECONDS.toMillis(10));
			second.join(TimeUnit.SECONDS.toMillis(10));
			closer.join(TimeUnit.SECONDS.toMillis(10));
		}
		assertThat(first.isAlive()).isFalse();
		assertThat(second.isAlive()).isFalse();
		assertThat(closer.isAlive()).isFalse();
		assertThat(firstFailure.get()).isInstanceOf(SailException.class)
				.hasMessage("pattern read interrupted during shutdown");
		assertThat(secondFailure.get()).isInstanceOf(SailException.class)
				.hasMessage("pattern read interrupted during shutdown");
		assertThat(closeFailure.get()).isNull();
		assertThat(teardownStarted.get()).isTrue();
	}

	private static void read(AbstractSailConnection connection, StatementPattern pattern,
			AtomicReference<Throwable> failure) {
		try (CloseableIteration<? extends Statement> ignored = connection.getStatements(pattern, null, null, null,
				false)) {
			// The delegate remains blocked until the closer has signalled both workers.
		} catch (Throwable thrown) {
			failure.set(thrown);
		}
	}
}
